#!/bin/bash
set -e

echo "==> Optometry/Doctor History: multiple Chief Complaint entries (per-eye complaint, duration, laterality) + OPD Case Sheet print support"

if [ ! -d "app/(main)/surgical-journey" ]; then
  echo "ERROR: run this from the root of the veda-hmis repo (app/(main)/surgical-journey not found here)."
  exit 1
fi

cat > /tmp/multi_chief_complaint.patch << 'PATCH_EOF'
