rgin-bottom: 6px;\">\n    <div style=\"font-size: 11.5px; font-weight: 800; text-transform: uppercase; letter-spacing: .4px; color: #1a3a5c; margin: 10px 0 5px; padding-bottom: 3px; border-bottom: 1.5px solid #c7d2e0;\">Diagnosis</div>\n    <ul style=\"margin: 0; padding-left: 18px; font-size: 10.5px; line-height: 1.4;\">\n      {{#each diagnoses}}\n      <li>{{name}} -- {{eye}}{{#if notes}} ({{notes}}){{/if}}</li>\n      {{/each}}\n    </ul>\n  </div>\n  {{/if}}\n\n  <!-- INVESTIGATIONS ADVISED -->\n  {{#if hasInvestigations}}\n  <div style=\"margin-bottom: 6px;\">\n    <div style=\"font-size: 11.5px; font-weight: 800; text-transform: uppercase; letter-spacing: .4px; color: #1a3a5c; margin: 10px 0 5px; padding-bottom: 3px; border-bottom: 1.5px solid #c7d2e0;\">Investigations Advised</div>\n    <ul style=\"margin: 0; padding-left: 18px; font-size: 10.5px; line-height: 1.4;\">\n      {{#each investigations}}\n      <li>{{name}} -- {{eye}}{{#if priority}} <span style=\"font-size: 9px; font-weight: 700; color: #b45309; text-transform: uppercase;\">({{priority}})</span>{{/if}}</li>\n      {{/each}}\n    </ul>\n  </div>\n  {{/if}}\n\n  <!-- SURGERY ADVISED -->\n  {{#if hasSurgery}}\n  <div style=\"margin-bottom: 6px;\">\n    <div style=\"font-size: 11.5px; font-weight: 800; text-transform: uppercase; letter-spacing: .4px; color: #1a3a5c; margin: 10px 0 5px; padding-bottom: 3px; border-bottom: 1.5px solid #c7d2e0;\">Surgery Advised</div>\n    <div style=\"font-size: 10.5px;\">{{surgery_procedure_name}} -- {{surgery_eye}}</div>\n  </div>\n  {{/if}}\n\n  <!-- MINOR PROCEDURES ADVISED -->\n  {{#if hasProcedures}}\n  <div style=\"margin-bottom: 6px;\">\n    <div style=\"font-size: 11.5px; font-weight: 800; text-transform: uppercase; letter-spacing: .4px; color: #1a3a5c; margin: 10px 0 5px; padding-bottom: 3px; border-bottom: 1.5px solid #c7d2e0;\">Minor Procedures Advised</div>\n    <ul style=\"margin: 0; padding-left: 18px; font-size: 10.5px; line-height: 1.4;\">\n      {{#each procedures}}\n      <li>{{name}} -- {{eye}}{{#if notes}} ({{notes}}){{/if}}</li>\n      {{/each}}\n    </ul>\n  </div>\n  {{/if}}\n\n  <!-- PRESCRIPTION -->\n  {{#if hasPrescriptions}}\n  <div style=\"margin-bottom: 6px;\">\n    <div style=\"font-size: 11.5px; font-weight: 800; text-transform: uppercase; letter-spacing: .4px; color: #1a3a5c; margin: 10px 0 5px; padding-bottom: 3px; border-bottom: 1.5px solid #c7d2e0;\">Prescription (Rx)</div>\n    <table style=\"width: 100%; border-collapse: collapse; font-size: 10px;\">\n      <tr style=\"background: #e9edf2;\">\n        <th style=\"border: 1px solid #999; padding: 4px 4px; text-align: left;\">Medicine</th>\n        <th style=\"border: 1px solid #999; padding: 4px 4px;\">Eye</th>\n        <th style=\"border: 1px solid #999; padding: 4px 4px;\">Dosage</th>\n        <th style=\"border: 1px solid #999; padding: 4px 4px;\">Frequency</th>\n        <th style=\"border: 1px solid #999; padding: 4px 4px;\">Duration</th>\n      </tr>\n      {{#each prescriptions}}\n      <tr>\n        <td style=\"border: 1px solid #999; padding: 4px 4px;\">{{drug}}{{#if isTaper}} <span style=\"font-size: 9px; font-weight: 700; color: #7c3aed; text-transform: uppercase;\">(Taper)</span>{{/if}}</td>\n        <td style=\"border: 1px solid #999; padding: 4px 4px; text-align: center;\">{{eye}}</td>\n        <td style=\"border: 1px solid #999; padding: 4px 4px; text-align: center;\">{{dosage}}</td>\n        {{#if isTaper}}\n        <td colspan=\"2\" style=\"border: 1px solid #999; padding: 4px 4px; text-align: center; font-size: 9.5px;\">{{frequency}}</td>\n        {{else}}\n        <td style=\"border: 1px solid #999; padding: 4px 4px; text-align: center;\">{{frequency}}</td>\n        <td style=\"border: 1px solid #999; padding: 4px 4px; text-align: center;\">{{duration}}</td>\n        {{/if}}\n      </tr>\n      {{/each}}\n    </table>\n  </div>\n  {{/if}}\n\n  <!-- REFERRAL -->\n  {{#if hasReferrals}}\n  <div style=\"margin-bottom: 6px;\">\n    <div style=\"font-size: 11.5px; font-weight: 800; text-transform: uppercase; letter-spacing: .4px; color: #1a3a5c; margin: 10px 0 5px; padding-bottom: 3px; border-bottom: 1.5px solid #c7d2e0;\">Referral</div>\n    <ul style=\"margin: 0; padding-left: 18px; font-size: 10.5px; line-height: 1.4;\">\n      {{#each referrals}}\n      <li>{{destination}}{{#if reason}} -- {{reason}}{{/if}}</li>\n      {{/each}}\n    </ul>\n  </div>\n  {{/if}}\n\n  <!-- ADVICE -->\n  {{#if advice}}\n  <div style=\"margin-bottom: 6px;\">\n    <div style=\"font-size: 11.5px; font-weight: 800; text-transform: uppercase; letter-spacing: .4px; color: #1a3a5c; margin: 10px 0 5px; padding-bottom: 3px; border-bottom: 1.5px solid #c7d2e0;\">Advice</div>\n    <div style=\"font-size: 10.5px; white-space: pre-wrap; line-height: 1.35;\">{{advice}}</div>\n  </div>\n  {{/if}}\n\n  <!-- FOLLOW UP -->\n  {{#if followup_text}}\n  <div style=\"background: #e7eff8; border: 1px solid #1e4e8c; border-radius: 8px; padding: 5px 10px; font-size: 10.5px; color: #123a66; margin-bottom: 6px; margin-top: 2px;\">\n    <strong>Follow-up:</strong> {{followup_text}}\n  </div>\n  {{/if}}\n\n  <table style=\"width: 100%; margin-top: 12px;\">\n    <tr>\n      <td style=\"font-size: 10.5px;\">&nbsp;</td>\n      <td style=\"text-align: right; font-size: 10.5px;\">\n        <div style=\"height: 55px;\">&nbsp;</div>\n        <div style=\"border-top: 1px solid #333; width: 210px; margin-left: auto; padding-top: 5px; font-weight: 700;\">{{doctor_name}}</div>\n        <div style=\"font-size: 9.5px; color: #444;\">Reg No: {{doctor_regn_no}}</div>\n      </td>\n    </tr>\n  </table>\n\n  <div style=\"text-align: center; margin-top: 6px; font-size: 9px; color: #888;\">\n    For any Queries please contact us at {{hospital_phone}} or Email us at {{hospital_email}}\n  </div>\n</div>\n",
+  opd_case_sheet: "<style>\n  @media print {\n    @page { size: A4; margin: {{#if hide_header}}{{header_space_cm}}cm{{else}}8mm{{/if}} 10mm 8mm 10mm; }\n  }\n</style>\n<div style=\"max-width: 800px; margin: 0 auto; padding: 10px 16px; font-family: Arial, Helvetica, sans-serif; color: #000; font-size: 10.5px; line-height: 1.32;\">\n\n  {{#unless hide_header}}\n  <!-- HEADER -->\n  <table style=\"width: 100%; border-collapse: collapse; margin-bottom: 3px;\">\n    <tr>\n      <td style=\"width: 100px; vertical-align: top;\">{{{logo_html}}}</td>\n      <td style=\"vertical-align: top;\">\n        <div style=\"font-size: 16px; font-weight: 800; letter-spacing: .3px; text-decoration: underline;\">{{hospital_name}}</div>\n        <div style=\"font-size: 9.5px; font-weight: 700; margin-top: 3px;\">{{hospital_unit_line}}</div>\n        <div style=\"font-size: 9px; font-weight: 700;\">REGN NO : {{hospital_regn_no}}</div>\n      </td>\n      <td style=\"text-align: right; vertical-align: top; font-size: 9.5px; line-height: 1.6;\">\n        {{hospital_address_line1}}<br/>\n        {{hospital_address_line2}}<br/>\n        {{hospital_city_state_pin}}<br/>\n        Tel: {{hospital_phone}}\n      </td>\n    </tr>\n  </table>\n  {{/unless}}\n  {{#if hide_header}}<!-- Blank space for the pad's pre-printed header is reserved by the @page top margin above, so it repeats on every printed page, not just the first. -->{{/if}}\n\n  <div style=\"text-align: center; font-size: 14px; font-weight: 800; letter-spacing: .4px; border-top: 1.5px solid #333; border-bottom: 1.5px solid #333; padding: 4px 0; margin: 4px 0 6px;\">\n    OPD CASE SHEET\n  </div>\n\n  <!-- PATIENT / VISIT INFO -->\n  <table style=\"width: 100%; border: 1.5px solid #333; border-collapse: collapse; margin-bottom: 8px;\">\n    <tr>\n      <td style=\"width: 50%; padding: 6px 10px; vertical-align: top; font-size: 10.5px; line-height: 1.4; border-right: 1px solid #ccc;\">\n        <table style=\"width: 100%; font-size: 10.5px;\">\n          <tr><td style=\"width: 120px; color: #222;\">PATIENT ID</td><td>: <strong>{{patient_id}}</strong></td></tr>\n          <tr><td style=\"color: #222;\">NAME</td><td>: <strong>{{patient_name}}</strong></td></tr>\n          <tr><td style=\"color: #222;\">AGE/GENDER</td><td>: <strong>{{patient_age}} / {{patient_gender}}</strong></td></tr>\n          <tr><td style=\"color: #222;\">MOBILE</td><td>: <strong>{{patient_mobile}}</strong></td></tr>\n        </table>\n      </td>\n      <td style=\"width: 50%; padding: 6px 10px; vertical-align: top; font-size: 10.5px; line-height: 1.4;\">\n        <table style=\"width: 100%; font-size: 10.5px;\">\n          <tr><td style=\"width: 120px; color: #222;\">VISIT DATE</td><td>: <strong>{{visit_date}}</strong></td></tr>\n          <tr><td style=\"color: #222;\">VISIT TYPE</td><td>: <strong>{{visit_type}}</strong></td></tr>\n          <tr><td style=\"color: #222;\">DOCTOR</td><td>: <strong>{{doctor_name}}</strong></td></tr>\n          <tr><td style=\"color: #222;\">DOCTOR REGN NO</td><td>: <strong>{{doctor_regn_no}}</strong></td></tr>\n        </table>\n      </td>\n    </tr>\n  </table>\n\n  <!-- CHIEF COMPLAINT -->\n  {{#if hasChiefComplaints}}\n  <div style=\"margin-bottom: 6px;\">\n    <div style=\"font-size: 11.5px; font-weight: 800; text-transform: uppercase; letter-spacing: .4px; color: #1a3a5c; margin: 10px 0 5px; padding-bottom: 3px; border-bottom: 1.5px solid #c7d2e0;\">Chief Complaint</div>\n    <table style=\"width: 100%; font-size: 10.5px; border-collapse: collapse;\">\n      {{#each chiefComplaints}}\n      <tr>\n        <td style=\"padding: 2px 6px 2px 0; vertical-align: top; width: 14px; color: #1a3a5c; font-weight: 700;\">{{#if ../multipleComplaints}}&bull;{{/if}}</td>\n        <td style=\"padding: 2px 0;\">{{text}}{{#if duration}} &ndash; {{duration}}{{/if}}{{#if laterality}} ({{laterality}}){{/if}}</td>\n      </tr>\n      {{/each}}\n    </table>\n    {{#if hx_hopi}}<div style=\"font-size: 10.5px; col