: 4px 4px; width: 8%;\">AXIS</th>\n        <th style=\"border: 1px solid #999; padding: 4px 4px; width: 8%;\">PRISM</th>\n        <th style=\"border: 1px solid #999; padding: 4px 4px; width: 8%;\">VISION</th>\n      </tr>\n      <tr>\n        <td style=\"border: 1px solid #999; padding: 4px 4px; font-weight: 700;\">Dist.</td>\n        <td style=\"border: 1px solid #999; padding: 4px 4px; text-align: center; font-weight: 600;\">{{dist_re_sph}}</td>\n        <td style=\"border: 1px solid #999; padding: 4px 4px; text-align: center;\">{{dist_re_cyl}}</td>\n        <td style=\"border: 1px solid #999; padding: 4px 4px; text-align: center;\">{{dist_re_axis}}</td>\n        <td style=\"border: 1px solid #999; padding: 4px 4px; text-align: center;\">{{dist_re_prism}}</td>\n        <td style=\"border: 1px solid #999; padding: 4px 4px; text-align: center;\">{{dist_re_va}}</td>\n        <td style=\"border: 1px solid #999; padding: 4px 4px; text-align: center; font-weight: 600; border-left: 2px solid #999;\">{{dist_le_sph}}</td>\n        <td style=\"border: 1px solid #999; padding: 4px 4px; text-align: center;\">{{dist_le_cyl}}</td>\n        <td style=\"border: 1px solid #999; padding: 4px 4px; text-align: center;\">{{dist_le_axis}}</td>\n        <td style=\"border: 1px solid #999; padding: 4px 4px; text-align: center;\">{{dist_le_prism}}</td>\n        <td style=\"border: 1px solid #999; padding: 4px 4px; text-align: center;\">{{dist_le_va}}</td>\n      </tr>\n      <tr>\n        <td style=\"border: 1px solid #999; padding: 4px 4px; font-weight: 700;\">NEAR ADD</td>\n        <td style=\"border: 1px solid #999; padding: 4px 4px; text-align: center; font-weight: 600;\" colspan=\"4\">{{near_add_re}}</td>\n        <td style=\"border: 1px solid #999; padding: 4px 4px; text-align: center;\">{{#if hasNearRx}}{{near_re_va}}{{else}}--{{/if}}</td>\n        <td style=\"border: 1px solid #999; padding: 4px 4px; text-align: center; font-weight: 600; border-left: 2px solid #999;\" colspan=\"4\">{{near_add_le}}</td>\n        <td style=\"border: 1px solid #999; padding: 4px 4px; text-align: center;\">{{#if hasNearRx}}{{near_le_va}}{{else}}--{{/if}}</td>\n      </tr>\n    </table>\n  </div>\n  {{else}}\n  {{#if hasNearRx}}\n  <div style=\"margin-bottom: 6px;\">\n    <div style=\"font-size: 11.5px; font-weight: 800; text-transform: uppercase; letter-spacing: .4px; color: #1a3a5c; margin: 10px 0 5px; padding-bottom: 3px; border-bottom: 1.5px solid #c7d2e0;\">Refraction (Final Rx)</div>\n    <table style=\"width: 100%; border-collapse: collapse; font-size: 10px;\">\n      <tr style=\"background: #e9edf2;\">\n        <th style=\"border: 1px solid #999; padding: 4px 4px; text-align: left; width: 90px;\" rowspan=\"2\"></th>\n        <th style=\"border: 1px solid #999; padding: 4px 4px;\" colspan=\"5\">Right Eye (RE)</th>\n        <th style=\"border: 1px solid #999; padding: 4px 4px; border-left: 2px solid #999;\" colspan=\"5\">Left Eye (LE)</th>\n      </tr>\n      <tr style=\"background: #e9edf2;\">\n        <th style=\"border: 1px solid #999; padding: 4px 4px; width: 8%;\">SPH</th>\n        <th style=\"border: 1px solid #999; padding: 4px 4px; width: 8%;\">CYL</th>\n        <th style=\"border: 1px solid #999; padding: 4px 4px; width: 8%;\">AXIS</th>\n        <th style=\"border: 1px solid #999; padding: 4px 4px; width: 8%;\">PRISM</th>\n        <th style=\"border: 1px solid #999; padding: 4px 4px; width: 8%;\">VISION</th>\n        <th style=\"border: 1px solid #999; padding: 4px 4px; width: 8%; border-left: 2px solid #999;\">SPH</th>\n        <th style=\"border: 1px solid #999; padding: 4px 4px; width: 8%;\">CYL</th>\n        <th style=\"border: 1px solid #999; padding: 4px 4px; width: 8%;\">AXIS</th>\n        <th style=\"border: 1px solid #999; padding: 4px 4px; width: 8%;\">PRISM</th>\n        <th style=\"border: 1px solid #999; padding: 4px 4px; width: 8%;\">VISION</th>\n      </tr>\n      <tr>\n        <td style=\"border: 1px solid #999; padding: 4px 4px; font-weight: 700;\">NEAR ADD</td>\n        <td style=\"border: 1px solid #999; padding: 4px 4px; text-align: center; font-weight: 600;\" colspan=\"4\">{{near_add_re}}</td>\n        <td style=\"border: 1px solid #999; padding: 4px 4px; text-align: center;\">{{near_re_va}}</td>\n        <td style=\"border: 1px solid #999; padding: 4px 4px; text-align: center; font-weight: 600; border-left: 2px solid #999;\" colspan=\"4\">{{near_add_le}}</td>\n        <td style=\"border: 1px solid #999; padding: 4px 4px; text-align: center;\">{{near_le_va}}</td>\n      </tr>\n    </table>\n  </div>\n  {{/if}}\n  {{/if}}\n\n  {{#if hasGlassesSection}}\n  <table style=\"width: 100%; margin-bottom: 6px; font-size: 10px;\">\n    {{#if glasses_prescribed}}\n    <tr>\n      <td style=\"padding: 3px 0; color: #222; width: 140px;\">GLASSES PRESCRIBED</td>\n      <td style=\"padding: 3px 0; font-weight: 700;\">: YES</td>\n    </tr>\n    {{/if}}\n    {{#if hasGlassesType}}\n    <tr>\n      <td style=\"padding: 3px 0; color: #222; width: 140px;\">TYPE OF GLASS</td>\n      <td style=\"padding: 3px 0; font-weight: 700;\">: {{glasses_type}}</td>\n    </tr>\n    {{/if}}\n    {{#if hasGlassesRemarks}}\n    <tr>\n      <td style=\"padding: 3px 0; color: #222; width: 140px; vertical-align: top;\">REMARKS</td>\n      <td style=\"padding: 3px 0;\">: {{glasses_remarks}}</td>\n    </tr>\n    {{/if}}\n  </table>\n  {{/if}}\n\n  <!-- ADDITIONAL PRE-OP TESTS -->\n  {{#if hasAdditionalTests}}\n  <div style=\"margin-bottom: 6px;\">\n    <div style=\"font-size: 11.5px; font-weight: 800; text-transform: uppercase; letter-spacing: .4px; color: #1a3a5c; margin: 10px 0 5px; padding-bottom: 3px; border-bottom: 1.5px solid #c7d2e0;\">Additional Tests</div>\n    <table style=\"width: 100%; font-size: 10px; border-collapse: collapse;\">\n      {{#each additionalTests}}\n      <tr>\n        <td style=\"padding: 3px 0; width: 140px; color: #222;\">{{label}}</td>\n        <td style=\"padding: 3px 0;\">{{value}}</td>\n      </tr>\n      {{/each}}\n    </table>\n  </div>\n  {{/if}}\n\n  <!-- OPTOMETRY OBSERVATIONS -->\n  {{#if hasOptObservations}}\n  <div style=\"margin-bottom: 6px;\">\n    <div style=\"font-size: 11.5px; font-weight: 800; text-transform: uppercase; letter-spacing: .4px; color: #1a3a5c; margin: 10px 0 5px; padding-bottom: 3px; border-bottom: 1.5px solid #c7d2e0;\">Optometry Observations</div>\n    <div style=\"font-size: 10.5px;\">{{optObservations}}</div>\n  </div>\n  {{/if}}\n\n  <!-- EXAMINATION -->\n  {{#if hasExamination}}\n  <div style=\"margin-bottom: 6px;\">\n    <div style=\"font-size: 11.5px; font-weight: 800; text-transform: uppercase; letter-spacing: .4px; color: #1a3a5c; margin: 10px 0 5px; padding-bottom: 3px; border-bottom: 1.5px solid #c7d2e0;\">Examination Findings</div>\n\n    {{#each examPairs}}\n    <div style=\"display: flex; gap: 10px;\">\n      <div style=\"{{#if right}}flex: 1; min-width: 0;{{else}}width: 100%;{{/if}}\">\n        <div style=\"font-size: 10px; font-weight: 700; text-transform: uppercase; letter-spacing: .3px; color: #35507a; margin: 6px 0 4px; padding: 2px 0 2px 8px; border-left: 3px solid #7f9cc4;\">{{left.label}}</div>\n        <table style=\"width: 100%; border-collapse: collapse; font-size: 10px; margin-bottom: 8px;\">\n          <tr style=\"background: #e9edf2;\">\n            <th style=\"border: 1px solid #999; padding: 4px 4px; text-align: left; width: 42%;\"></th>\n            <th style=\"border: 1px solid #999; padding: 4px 4px; width: 29%;\">{{left.reHeader}}</th>\n            <th style=\"border: 1px solid #999; padding: 4px 4px; width: 29%;\">{{left.leHeader}}</th>\n          </tr>\n          {{#each left.rows}}\n          <tr>\n            <td style=\"border: 1px solid #999; padding: 4px 4px; font-weight: 600;\">{{structure}}</td>\n            <td style=\"border: 1px solid #999; padding: 4px 4px; text-align: center;\">{{re}}</td>\n            <td style=\"border: 1px solid #999; padding: 4px 4px; text-align: center;\">{{l